import { QueryClient, QueryClientProvider } from 'react-query';
import { ReactQueryDevtools } from "react-query/devtools";
import { Route, Routes } from "react-router-dom";
import './App.css';
import { GeneralContext } from './contextos/GeneralContext';
import { ParametrosPagina } from './paginas/ParametrosPagina/ParametrosPagina';
import { InicioPagina } from './paginas/InicioPagina/InicioPagina';
import { LoginPagina } from './paginas/LoginPagina/LoginPagina';
import { AdministradorPagina } from './paginas/UsuariosPaginas/AdministradorPagina';
import { UsuariosPagina } from './paginas/UsuariosPaginas/UsuariosPagina';
import { ClientesPagina } from './paginas/ClientesPaginas/ClientesPagina';
import { ClientePagina } from './paginas/ClientesPaginas/ClientePagina';
import { EnlacesPagina } from './paginas/EnlacesPaginas/EnlacesPagina';
import { EnlacePagina } from './paginas/EnlacesPaginas/EnlacePagina';
import { RecursosPagina } from './paginas/RecursosPaginas/RecursosPagina';
import { RecursoPagina } from './paginas/RecursosPaginas/RecursoPagina';
import { MensajesPagina } from './paginas/MensajesPaginas/MensajesPagina';
import { MensajePagina } from './paginas/MensajesPaginas/MensajePagina';




const queryClient = new QueryClient()

function App() {
  return (
    <>
      <GeneralContext>
        <QueryClientProvider client={queryClient}>
          <Routes>
              <Route path="/" element={<LoginPagina/>}/>
              <Route path="/inicio" element={<InicioPagina/>}/>
              <Route path="/parametros" element={<ParametrosPagina/>}/>
              <Route path="/usuarios" element={<UsuariosPagina/>}/>
              <Route path="/administrador/:administradorId" element={<AdministradorPagina/>}/>
              <Route path="/clientes" element={<ClientesPagina/>}/>
              <Route path="/cliente/:codclien" element={<ClientePagina/>}/>
              <Route path="/enlaces" element={<EnlacesPagina/>}/>
              <Route path="/enlace/:enlaceId" element={<EnlacePagina/>}/>
              <Route path="/recursos" element={<RecursosPagina/>}/>
              <Route path="/recurso/:recursoId" element={<RecursoPagina/>}/>
              <Route path="/mensajes" element={<MensajesPagina/>}/>
              <Route path="/mensaje/:mensajeId" element={<MensajePagina/>}/>
          </Routes>
          <ReactQueryDevtools initialIsOpen={false} position='bottom-right' />
        </QueryClientProvider>
      </GeneralContext>
    </>
  );
}

export default App;
