import { AppBar, Grid, IconButton, Toolbar, Tooltip, Typography} from '@mui/material'
import React, { useContext, useState } from 'react'
import { useMutation, useQuery } from 'react-query'
import { useNavigate } from 'react-router-dom'
import { MenuLateral } from '../../componentes/MenuLateral/MenuLateral'
import { MensajeError } from '../../utilidades/TratamientoErrores'
import { ErrorGeneral } from '../../componentes/ErrorGeneral/ErrorGeneral';
import { LeerRecursos, eliminarRecurso } from '../../servicios/RQRecursos'
import { GeneralCtx } from '../../contextos/GeneralContext'
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import { MensajeConfirmacion } from '../../componentes/MensajeConfirmacion/MensajeConfirmacion'
import { MensajeInformativo } from '../../componentes/MensajeInformativo/MensajeInformativo'
import { DataGrid, esES, GridToolbar } from '@mui/x-data-grid';


export const RecursosPagina = (props) => {
    const navigate = useNavigate()
    const { getSession } = useContext(GeneralCtx)
    const [hayError, setHayError] = useState(false)
    const [mensajeError, setMensajeError] = useState('')
    const [hayMensaje, setHayMensaje] = useState(false)
    const [mensaje, setMensaje] = useState('')
    const [hayConfirmacion, setHayConfirmacion] = useState(false)
    const [mensajeConfirmacion, setMensajeConfirmacion] = useState('')
    const [recursos, setRecursos] = useState([])
    const [recurso, setRecurso] = useState()    
    const session = getSession()
    const queryUsuarios = useQuery('recursos', () => { return LeerRecursos(session.empresa.empresaId) }, {
        onSuccess: (data) => {
            setRecursos(data.data)
        },
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })
    const eliminaRecurso = useMutation((recursoId) => { return eliminarRecurso(recursoId, session.empresa.empresaId) }, {
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })

    const newRecurso = () => {
        navigate(`/recurso/0`)
    }

    const editRecurso = (id) => {
        return () => {
            navigate(`/recurso/${id}`)
        }
    }

    const deleteRecurso = (row) => {
        return () => {
            setRecurso(row)
            setMensajeConfirmacion(`¿Realmente desea eliminar el recurso ${row.nombre}?`)
            setHayConfirmacion(true)
        }
    }

    const deleteConfirmado = async () => {
        await eliminaRecurso.mutateAsync(recurso.recursoId)
        queryUsuarios.refetch()
        setHayConfirmacion(false)
        setMensaje(`El recurso ${recurso.nombre} ha sido eliminado de la base de datos`)
        setHayMensaje(true)
    }

    const columns = [
        { field: 'recursoId', headerName: 'ID' },
        { field: 'nombre', headerName: 'nombre', flex: 1 },
        { field: 'url', headerName: 'url', flex: 1 },
        {
            field: 'actions',
            type: 'actions',
            headerName: 'Acciones',
            width: 80,
            getActions: ({row}) => {
                return [<IconButton onClick={deleteRecurso(row)}>
                    <DeleteIcon />
                </IconButton>,
                <IconButton onClick={editRecurso(row.recursoId)}>
                    <EditIcon />
                </IconButton>]
            }
        },
    ]

    return (
        <>
            <MenuLateral>
                <Grid container spacing={2}>
                    <Grid item xs={12}>
                        <AppBar id="imagen" position='static' color='secondary'>
                            <Toolbar>
                                <Typography variant='h6' component='h6'>
                                    Recursos
                                </Typography>
                                <span className='toolbarButtons'>
                                    <IconButton size="large" aria-label="Nuevo recurso" color="inherit" onClick={newRecurso}>
                                        <Tooltip title="Nuevo recurso" >
                                            <AddIcon />
                                        </Tooltip>
                                    </IconButton>
                                </span>
                            </Toolbar>
                        </AppBar>
                    </Grid>
                    <Grid item xs={12} style={{ height: '80vh', width: '100%' }}>
                        <DataGrid rows={recursos} columns={columns} getRowId={(row) => row.recursoId} components={{Toolbar: GridToolbar}}
                            localeText={esES.components.MuiDataGrid.defaultProps.localeText} />
                    </Grid>
                </Grid>
                <ErrorGeneral hayError={hayError} mensajeError={mensajeError} cerrarError={() => setHayError(false)} />
                <MensajeInformativo hayMensaje={hayMensaje} mensaje={mensaje} cerrarMensaje={() => setHayMensaje(false)} />
                <MensajeConfirmacion hayConfirmacion={hayConfirmacion} mensaje={mensajeConfirmacion} confirmar={deleteConfirmado} cerrarConfirmacion={() => setHayConfirmacion(false)} />
            </MenuLateral>
        </>

    )
}
