import axios from 'axios'
import Entorno from './Entorno'

export const Test = () => {
    return 'Test de RQ Parametros'
}

export const ObtenerUrl = () => {
    const ent = Entorno.gentEnv()
    return ent
}

export const ConsultarParametrosPorCodigoWeb = (cw) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/empresas/buscar-codigoweb/`
    const data = {
        codigoWeb: cw
    }
    return axios.post(url, data)
}

export const ConsultarParametrosPorAccUrl = (acu) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/empresas/buscar-accurl/`
    const data = {
        accUrl: acu
    }
    return axios.post(url, data)
}

export const ConsultarParametrosPorId = (id, empresa) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/parametros/${id}/${empresa.empresaId}`
    return axios.get(url)
}

export const ActualizarParametros = (parametros, empresaId) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/parametros/0/${empresaId}`
    return axios.put(url, {parametro: parametros})
}
