import { Grid, Typography } from '@mui/material'
import { Box } from '@mui/system'
import React from 'react'

export const LoginCabecera = ({ dtLogin, nombre }) => {
    return (
        <Box>
            <Grid container spacing={1}>
                <Grid item xs={4}>
                    <img src={dtLogin.accLogo} alt="logo" className='imagenLogo' />
                </Grid>
                <Grid item xs={8}>
                    <Typography variant='h6' component='h6'>
                        {nombre}
                    </Typography>
                    <Typography variant='subtitle2'>
                        (C) Ariadna Software SL (2023)
                    </Typography>
                </Grid>
            </Grid>
        </Box>
    )
}
