import axios from 'axios'
import Entorno from './Entorno'

export const Test = () => {
    return 'Test de RQ Parametros'
}

export const ObtenerUrl = () => {
    const ent = Entorno.gentEnv()
    return ent
}

export const LeerRecursos = (empresaId) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/recursos/${empresaId}`
    return axios.get(url)
}

export const LeerRecurso = (recursoId, empresaId) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/recursos/${recursoId}/${empresaId}`
    return axios.get(url)
}


export const CrearRecurso = (recurso) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/recursos`
    return axios.post(url, {recurso: recurso})
}


export const eliminarRecurso = (recursoId, empresaId) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/recursos/${recursoId}/${empresaId}`
    return axios.delete(url)
}

export const ActualizarRecurso = (recurso) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/recursos/${recurso.recursoId}`
    return axios.put(url, {recurso: recurso})
}
