export const ActualizarMensaje = (mensaje, empresaId) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/mensajes/${empresaId}/${mensaje.mensajeId}`
    return axios.put(url, { mensaje: mensaje })
}

