export const LeerClientesPushOpcion = (empresaId, q, tipo) => {
  const ent = Entorno.gentEnv();
  const url_base = ent.API_URL;
  const url = `${url_base}/api/clientes/logados/tipo/(${empresaId}`;
  return axios.get(url, {
    params: {
      q,      // texto que escribe el usuario
      tipo    // LICENCIA / NOMBRE / CODIGO
    }
  });
};
