import React, { useContext, useEffect, useState, } from 'react'
import { useParams } from 'react-router-dom'
import { MenuLateral } from '../../componentes/MenuLateral/MenuLateral'
import { useFormik } from 'formik';
import { useMutation, useQuery } from "react-query";
import { initialValues, validationSchema } from './MensajesFunciones'
import { useNavigate } from 'react-router-dom';
import { GeneralCtx } from '../../contextos/GeneralContext'
import { MensajeError } from '../../utilidades/TratamientoErrores'
import { ErrorGeneral } from '../../componentes/ErrorGeneral/ErrorGeneral';
import { CKEditor } from '@ckeditor/ckeditor5-react';
import ClassicEditor from '@ckeditor/ckeditor5-build-classic';
import { FormatoFechaEs } from "../../utilidades/TratamienfoFechas";
import {
    Autocomplete,
    Checkbox,
    AppBar,
    Button,
    Toolbar,
    Grid,
    TextField,
    Typography,
    FormControlLabel,
    FormControl,
    Tooltip,
    Radio,
    RadioGroup
} from '@mui/material';
import { DataGrid, esES, GridToolbar } from '@mui/x-data-grid';
import { ActualizarMensaje, CrearMensaje, EnviarMensaje, LeerMensaje, LeerClientesRelacionados, LeerClientesPushOpcion, SubirArchivo } from '../../servicios/RQMensajes';
import RocketLaunchIcon from '@mui/icons-material/RocketLaunch';
import { Label } from 'flowbite-react';
import DoneAllIcon from '@mui/icons-material/DoneAll';


export const MensajePagina = () => {
    const params = useParams()
    const navigate = useNavigate()
    const { getSession } = useContext(GeneralCtx)
    const [hayError, setHayError] = useState(false)
    const [mensajeError, setMensajeError] = useState('')
    const [mensaje, setMensaje] = useState({})
    const [clientes, setClientes] = useState([])
    const [enviarTodos, setEnviarTodos] = useState(false);
    const [tipoBusqueda, setTipoBusqueda] = useState("licencia");
    const [clientesPush, setClientesPush] = useState([]);
    const [selectedClientes, setSelectedClientes] = useState([]); // seleccionados
    const [inputValue, setInputValue] = useState(""); //texto escrito
    const [loading, setLoading] = useState(false);
    const [selectedOptions, setSelectedOptions] = useState([]);
    //const [initialValues, setInitialValues] = useState({ necesitaConfirmacion: false });
    const session = getSession();

    const handleSubmit = async (values) => {
        if (!values.mensajeId) {
            await crearMensaje.mutateAsync(values)
        } else {
            await actualizarMensaje.mutateAsync(values)
        }
        navigate('/mensajes')
    }


    const handleFileChange = async (event) => {
        const formData = new FormData();
        formData.append('file', event.target.files[0]);

        let result = await subirArchivo.mutateAsync(formData);
        setMensaje(result)
        formik.setFieldValue('fichero', event.target.files[0].name);
        formik.setFieldValue('usuPush', [])
    };

    const formik = useFormik({
        initialValues: initialValues(),
        validationSchema: validationSchema(),
        onSubmit: handleSubmit,
    });

    const salirForm = (e) => {
        if (e) e.preventDefault()
        navigate('/mensajes')
    }

    const enviar = async () => {
        // Validar el formulario antes de realizar la acción deseada
        const valoresActuales = formik.values; // <-- estos están siempre al día
        console.log(valoresActuales.asunto);


        if (!valoresActuales.asunto || valoresActuales.asunto == '' || !valoresActuales.texto || valoresActuales.texto == '') {
            try {
                throw new Error('Formulario no válido. No se realiza la acción.')
            } catch (e) {
                setMensajeError(MensajeError(e))
                setHayError(true);
            }
        } else {
            try {
                // Recuperar el valor de usuPush
                const usuPush = formik.getFieldProps('usuPush').value;
                const fichero = formik.getFieldProps('fichero').value;
                if (usuPush.length == 0 && fichero === "" && !enviarTodos) {
                    throw new Error('Formulario no válido, No se han incluido destinatarios.');
                }
                realizarEnvio();
            } catch (e) {
                setMensajeError(MensajeError(e))
                setHayError(true);
            }

        }

    }


    const realizarEnvio = async () => {
        var rows = [];
        var v = formik.values;
        if (enviarTodos) {
            for (let i = 0; i < clientesPush.length; i++) {
                rows.push(clientesPush[i].value);
            }
            v.usuPush = rows;
        }

        await enviarMensaje.mutateAsync(v)
        if (!hayError) navigate('/mensajes');
    }



    const actualizarMensaje = useMutation((mensaje) => { return ActualizarMensaje(mensaje, session.empresa.empresaId) }, {
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })

    const crearMensaje = useMutation((mensaje) => { return CrearMensaje(mensaje, session.empresa.empresaId) }, {
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })

    const enviarMensaje = useMutation((mensaje) => { return EnviarMensaje(mensaje, session.empresa.empresaId) }, {
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    });

    const subirArchivo = useMutation((f) => { return SubirArchivo(f) }, {
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    });

    const handleChangeBusqueda = (event) => {
        setTipoBusqueda(event.target.value);
    };



    //Recuperamos el mensaje
    useQuery(['mensaje', params.mensajeId], () => { return LeerMensaje(params.mensajeId, session.empresa.empresaId) }, {
        onSuccess: (data, variables, context) => {
            delete data.data.responsable
            if (data.data.necesitaConfirmacion == 1) { data.data.necesitaConfirmacion = true } else { data.data.necesitaConfirmacion = false }
            formik.setValues({ ...formik.values, ...data.data });
            setMensaje(data.data);

        },
        onError: (error, variables, context) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        },
        enabled: params.mensajeId !== '0'
    })

    //Recupramos los taxistas Relacionados con el mensaje y los combinamos con los seleccionados en el Autocomplete (si los hay)
    useQuery(
        ['clientes', params.mensajeId, session.empresa.empresaId],
        () => LeerClientesRelacionados(params.mensajeId, session.empresa.empresaId),
        {
            onSuccess: (data) => {
                setClientes(data.data); // para el DataGrid

                // Solo actualizamos usuPush, no selectedOptions
                const relacionados = data.data
                    .filter(c => c.codclien)
                    .map(c => c.codclien);

                // Combinamos con los que ya están seleccionados vía Autocomplete
                const seleccionados = selectedOptions.map(o => o.value);
                formik.setFieldValue(
                    'usuPush',
                    Array.from(new Set([...relacionados, ...seleccionados]))
                );
            },
            onError: (error) => {
                console.error(error);
                setMensajeError(MensajeError(error));
                setHayError(true);
            },
        }
    );



    //Recuperamos los taxistas que tienen playerId para cargar el Autocomplete (solo se visualiza en la creación de mensaje)
    /*    useQuery(['clientesPush', session.empresa.empresaId], () => { return LeerClientesPush(session.empresa.empresaId) }, {
           onSuccess: (data, variables, context) => {
               //formateamos los valores
               var c = data.data;
               var rows = [];
               for (let i = 0; i < c.length; i++) {
                   var obj = {
                       value: c[i].codclien,
                       label: c[i].nomclien
                   }
                   rows.push(obj);
               }
               setClientesPush(rows);
               //toggleVisibility()
           },
           onError: (error, variables, context) => {
               console.error(error)
               setMensajeError(MensajeError(error))
               setHayError(true)
           },
       })
    */


    useEffect(() => {
        formik.setFieldValue('empresaId', session.empresa.empresaId);
        formik.setFieldValue('administradorId', session.administrador.codusu);
    }, []);

    /*  useEffect(() => {
         if (!inputValue) return;
 
         const fetchClientes = async () => {
             setLoading(true);
             try {
                 console.log("Buscando:", inputValue, "Tipo:", tipoBusqueda);
                 const res = await LeerClientesPushOpcion(session.empresa.empresaId, inputValue, tipoBusqueda);
 
                 console.log("Resultados API:", res.data);
 
                 const rows = res.data.map(c => ({
                     value: c.codclien,
                     label: "(" + c.licencia + ") " + c.nomclien + " (" + c.codclien + ")"
                 }));
                 setClientesPush(rows);
             } catch (err) {
                 console.error(err);
             } finally {
                 setLoading(false);
             }
         };
 
         fetchClientes();
     }, [inputValue, tipoBusqueda]); */

    useEffect(() => {
        if (!inputValue) return;

        const timeout = setTimeout(async () => {
            setLoading(true);
            try {
                const res = await LeerClientesPushOpcion(session.empresa.empresaId, inputValue, tipoBusqueda);

                // siempre mostrar nomclien en la lista
                const rows = res.data.map(c => ({
                    value: c.codclien,
                    label: "(" + c.licencia + ") " + c.nomclien + " (" + c.codclien + ")",
                    codclien: c.codclien,
                    licencia: c.licencia
                }));

                setClientesPush(rows);
            } catch (err) {
                console.error(err);
            } finally {
                setLoading(false);
            }
        }, 400);

        return () => clearTimeout(timeout);
    }, [inputValue, tipoBusqueda]);


    const handleSelectChange = (event) => {
        const selectedValues = Array.from(event, (option) => option.value);
        formik.setFieldValue('usuPush', selectedValues)
    };

    const columns = [
        { field: 'codclien', headerName: 'ID' },
        { field: 'nombre', headerName: 'Cliente', flex: 1 },
        {
            field: 'textoRespuesta',
            headerName: 'Respuesta',
            flex: 1,
            renderCell: (params) => {
                const value = params.value || '';

                return (
                    <Tooltip
                        arrow
                        title={
                            <Typography sx={{ fontSize: '0.8rem', whiteSpace: 'pre-line' }}>
                                {value}
                            </Typography>
                        }
                    >
                        <Typography
                            noWrap
                            sx={{

                                overflow: 'hidden',
                                textOverflow: 'ellipsis',
                                whiteSpace: 'nowrap',
                                maxWidth: '100%',
                            }}
                        >
                            {value}
                        </Typography>
                    </Tooltip>
                );
            }
        },
        {
            field: 'confirmado',
            headerName: 'Confirmado',
            width: 120,
            renderCell: (params) => {
                const confirmado = params.value;

                return confirmado ? (
                    <DoneAllIcon sx={{ color: 'green' }} />
                ) : '';
            }
        },
        { field: 'estado', headerName: 'Estado' },
        { field: 'telefono1', headerName: 'Telefono 1' },
        { field: 'email', headerName: 'Email', width: 300 },
        {
            field: 'fechalec', headerName: 'Fecha lectura', type: 'date', width: 180,
            valueFormatter: params =>
                FormatoFechaEs(params.value),
        }
    ]




    return (
        <>
            <MenuLateral>
                <form onSubmit={formik.handleSubmit}>
                    <Grid container spacing={2}>
                        <Grid item xs={6}>
                            <Typography variant='h6'>Datos de mensaje:</Typography>
                        </Grid>
                        <Grid item xs={6} sx={{ textAlign: 'right' }}>
                            <Button color="success" variant="contained" onClick={salirForm}>
                                Salir
                            </Button>
                            <Button color="primary" variant="contained" type="submit" sx={{ marginLeft: 2 }}>
                                Aceptar
                            </Button>
                            <Button color="success" variant="contained" sx={{ marginLeft: 2 }} onClick={enviar}>
                                <RocketLaunchIcon /> Enviar
                            </Button>
                        </Grid>
                        <Grid item xs={2} md={1}>
                            <TextField fullWidth id="mensajeId" name="mensajeId" label="ID" disabled
                                value={formik.values.mensajeId}
                                onChange={formik.handleChange}
                                error={formik.touched.mensajeId && Boolean(formik.errors.mensajeId)}
                                helperText={formik.touched.mensajeId && formik.errors.mensajeId}
                            />
                        </Grid>
                        <Grid item xs={2} md={8}>
                        </Grid>
                        <Grid item xs={3} md={3}>
                            <FormControlLabel style={{ marginLeft: '18%' }}
                                control={
                                    <Checkbox
                                        checked={formik.values.necesitaConfirmacion}
                                        onChange={formik.handleChange}
                                        name="necesitaConfirmacion"
                                    />
                                }
                                label="Necesita confirmación"
                            />

                        </Grid>

                        <Grid item xs={12} md={12}>
                            <TextField fullWidth id="asunto" name="asunto" label="Asunto"
                                value={formik.values.asunto}
                                onChange={formik.handleChange}
                                error={formik.touched.asunto && Boolean(formik.errors.asunto)}
                                helperText={formik.touched.asunto && formik.errors.asunto}
                            />
                        </Grid>
                        <Grid item xs={12} md={12}>
                            <label>Texto</label>
                            <div style={{ height: '40vh', width: '100%', overflow: 'scroll' }}>
                                <CKEditor id="texto" name="texto" label="Texto"
                                    editor={ClassicEditor}
                                    data={formik.values.texto}
                                    config={{
                                        language: 'es'
                                    }}
                                    onReady={editor => {
                                        // You can store the "editor" and use when it is needed.
                                        console.log('Editor is ready to use!', editor);
                                    }}
                                    onChange={(event, editor) => {
                                        const data = editor.getData();
                                        formik.setFieldValue('texto', data)
                                    }}
                                    onBlur={(event, editor) => {
                                        console.log('Blur.', editor);
                                    }}
                                    onFocus={(event, editor) => {
                                        console.log('Focus.', editor);
                                    }}
                                />
                            </div>

                        </Grid>
                        <Grid item xs={12} md={6}>
                        </Grid>
                    </Grid>

                    <Grid id="clientesP" container spacing={5} sx={{ marginTop: '10px' }}>
                        <Grid item xs={5} md={5} >
                            <label>Buscar destinatarios por</label><br></br>
                            <FormControl>
                                <RadioGroup
                                    row
                                    value={tipoBusqueda}
                                    onChange={handleChangeBusqueda}
                                    name="tipo-busqueda"
                                >
                                    <FormControlLabel
                                        value="licencia"
                                        control={<Radio />}
                                        label="Licencia"
                                    />
                                    <FormControlLabel
                                        value="nomclien"
                                        control={<Radio />}
                                        label="Nombre"
                                    />
                                    <FormControlLabel
                                        value="codclien"
                                        control={<Radio />}
                                        label="Código"
                                    />
                                </RadioGroup>
                            </FormControl>
                        </Grid>
                        <Grid item xs={4} md={4}>
                            <label >Enviar a todos los taxistas</label>
                            <Checkbox
                                onChange={(event, option) => {
                                    console.log(clientesPush);
                                    if (option) {
                                        setEnviarTodos(true);
                                        return;
                                    }
                                    setEnviarTodos(false);
                                }} />
                        </Grid>

                        <Grid item xs={3} md={3} sx={{ textAlign: 'right' }}>
                            <div className="mb-2"> {/* Agregamos la clase "mb-2" para el margen inferior */}
                                <Label htmlFor="uploadFile" value="Seleccionar destinatarios desde archivo" />
                            </div>
                            <div className="d-block"> {/* Agregamos la clase "d-block" para convertir el elemento en un bloque en línea */}
                                <input type="file" id="uploadImage" name="uploadImage" onChange={handleFileChange} className="form-control" style={{ borderRadius: '0.5rem' }} />
                            </div>
                        </Grid>

                        <Grid item xs={12} md={12}>
                            <Autocomplete
                                multiple
                                options={clientesPush.filter(
                                    option => !clientes.some(c => c.codclien === option.value) // filtramos los ya relacionados
                                )}
                                value={selectedOptions} // solo los seleccionados vía Autocomplete
                                isOptionEqualToValue={(option, value) => option.value === value.value}
                                onChange={(_, selected) => {
                                    setSelectedOptions(selected);
                                    // Actualizamos usuPush: combinamos los relacionados + seleccionados
                                    const relacionados = clientes.map(c => c.codclien);
                                    const seleccionados = selected.map(o => o.value);
                                    formik.setFieldValue('usuPush', Array.from(new Set([...relacionados, ...seleccionados])));
                                }}
                                inputValue={inputValue}
                                onInputChange={(_, newInputValue) => setInputValue(newInputValue)}
                                loading={loading}
                                getOptionLabel={(option) => option.label} // siempre nomclien
                                renderInput={(params) => (
                                    <TextField
                                        {...params}
                                        variant="outlined"
                                        label="Seleccionar destinatarios"
                                        error={formik.touched.usuPush && Boolean(formik.errors.usuPush)}
                                        helperText={formik.touched.usuPush && formik.errors.usuPush}
                                    />
                                )}
                            />
                        </Grid>

                        <Grid item xs={12} md={6}>
                        </Grid>
                        <Grid item xs={6} sx={{ textAlign: 'right' }}>
                            <Button color="success" variant="contained" onClick={salirForm}>
                                Salir
                            </Button>
                            <Button color="primary" variant="contained" type="submit" sx={{ marginLeft: 2 }}>
                                Aceptar
                            </Button>
                            <Button color="success" variant="contained" sx={{ marginLeft: 2 }} onClick={enviar}>
                                <RocketLaunchIcon /> Enviar
                            </Button>
                        </Grid>
                        <Grid item xs={12} md={6}>
                        </Grid>
                    </Grid>
                    {/* } */}
                    <Grid id="relacionados" container spacing={2}>

                        {/* grid de clientes relacionados del mensaje */}

                        <Grid item xs={12}>
                            <AppBar id="imagen" position='static' color='secondary'>
                                <Toolbar>
                                    <Typography variant='h6' component='h6'>
                                        Clientes relacionados
                                    </Typography>
                                </Toolbar>
                            </AppBar>
                        </Grid>
                        <Grid item xs={12} style={{ height: '45vh', width: '100%' }}>
                            <DataGrid rows={clientes} columns={columns} getRowId={(row) => row.codclien} components={{ Toolbar: GridToolbar }}
                                localeText={esES.components.MuiDataGrid.defaultProps.localeText} />
                        </Grid>
                        <Grid item xs={12} md={6}>
                        </Grid>
                    </Grid>
                    {/* : */}


                </form>
                <ErrorGeneral hayError={hayError} mensajeError={mensajeError} cerrarError={() => setHayError(false)} />
            </MenuLateral>
        </>
    )
}
