import axios from 'axios'
import Entorno from './Entorno'

export const Test = () => {
    return 'Test de RQ Parametros'
}

export const ObtenerUrl = () => {
    const ent = Entorno.gentEnv()
    return ent
}

export const LeerEnlaces = (empresaId) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/enlaces/${empresaId}`
    return axios.get(url)
}

export const LeerEnlace = (enlaceId, empresaId) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/enlaces/${enlaceId}/${empresaId}`
    return axios.get(url)
}


export const CrearEnlace = (enlace) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/enlaces`
    return axios.post(url, {enlace: enlace})
}


export const eliminarEnlace = (enlaceId, empresaId) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/enlaces/${enlaceId}/${empresaId}`
    return axios.delete(url)
}

export const ActualizarEnlace = (enlace) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/enlaces/${enlace.enlaceId}`
    return axios.put(url, {enlace: enlace})
}
