import { useFormik } from 'formik';
import { useMutation } from "react-query";
import * as yup from 'yup';
import React, { useContext, useEffect, useState } from 'react'
import { Button, Grid, TextField } from '@mui/material';

import { LoginCabecera } from './LoginCabecera';
import './LoginPagina.css'
import { LoginBasicoAdministrador } from '../../servicios/RQUsuarios'
import { GeneralCtx } from '../../contextos/GeneralContext'
import { MensajeError} from '../../utilidades/TratamientoErrores'
import { ErrorGeneral } from '../../componentes/ErrorGeneral/ErrorGeneral';
import { MensajeInformativo } from '../../componentes/MensajeInformativo/MensajeInformativo';
import { useNavigate } from 'react-router-dom';

const validationSchema = yup.object({
    login: yup
        .string('Introduzca su login')
        .required('Requerido'),
    password: yup
        .string('Introduzca su contraseña')
        .required('Requerido'),
});

export const LoginForm = (props) => {
    const {setSession} = useContext(GeneralCtx)
    const [hayError, setHayError] = useState(false)
    const [mensajeError, setMensajeError] = useState('')
    const [hayMensaje, setHayMensaje] = useState(false)
    const [mensaje, setMensaje] = useState('')
    const navigate = useNavigate()

    const handleSubmit = async (values) => {
        // Cosultamos si la empresa existe
        let emp = { empresaId: 1}
        // Si superamos la búsqueda de empresa intentamos el login de administrador
        const { data: usu } = await loginBasico.mutateAsync({
            empresaId: emp.empresaId,
            login: values.login,
            password: values.password
        })
        // Guardamos en cookies los valores
        setSession(emp, usu)
        // Mostramos mensaje de OK
        setMensaje(`Login correcto en la empresa ${emp.nombre}`)
        setHayMensaje(true)
        // Nos vamos a inicio
        navigate('/inicio')
    }
    const formik = useFormik({
        initialValues: {
            login: '',
            password: '',
        },
        validationSchema: validationSchema,
        onSubmit: handleSubmit,
    });

    /* const buscaEmpresa = useMutation(cw => {
        return ConsultarEmpresaPorCodigoWeb(cw)
    }, {
        onSuccess: (data, variables, context) => {
            
        },
        onError: (error, variables, context) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    }) */

    const loginBasico = useMutation(loginData => {
        return LoginBasicoAdministrador(loginData)
    }, {
        onSuccess: (data, variables, context) => {

        },
        onError: (error, variables, context) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })

    useEffect(()=>{
        if (props.dtLogin.codigoWeb) formik.setFieldValue('empresa', props.dtLogin.codigoWeb)
    }, [])


    return (
        <div>
            <form onSubmit={formik.handleSubmit}>
                <Grid container spacing={2}>
                    <Grid item xs={12}>
                        <LoginCabecera dtLogin={props.dtLogin} nombre={props.nombre}/>
                    </Grid>
                    
                    <Grid item xs={12}>
                        <TextField
                            fullWidth
                            id="login"
                            name="login"
                            label="Administrador"
                            value={formik.values.login}
                            onChange={formik.handleChange}
                            error={formik.touched.login && Boolean(formik.errors.login)}
                            helperText={formik.touched.login && formik.errors.login}
                        />
                    </Grid>
                    <Grid item xs={12}>
                        <TextField
                            fullWidth
                            id="password"
                            name="password"
                            label="Contraseña"
                            type="password"
                            value={formik.values.password}
                            onChange={formik.handleChange}
                            error={formik.touched.password && Boolean(formik.errors.password)}
                            helperText={formik.touched.password && formik.errors.password}
                        />
                    </Grid>
                    <Grid item xs={12}>
                        <Button color="primary" variant="contained" fullWidth type="submit">
                            Entrar
                        </Button>
                    </Grid>
                </Grid>
            </form>
            <ErrorGeneral hayError={hayError} mensajeError={mensajeError} cerrarError={() => setHayError(false)}/>
            <MensajeInformativo hayMensaje={hayMensaje} mensaje={mensaje} cerrarMensaje={() => setHayMensaje(false)}/>
        </div>
    )
}
