import React, { useContext, useEffect, useState } from 'react'
import { useParams } from 'react-router-dom'
import { MenuLateral } from '../../componentes/MenuLateral/MenuLateral'
import { useFormik } from 'formik';
import { useMutation, useQuery } from "react-query";
import { initialValues, validationSchema } from './RecursosFunciones'
import { useNavigate } from 'react-router-dom';
import { GeneralCtx } from '../../contextos/GeneralContext'
import { MensajeError } from '../../utilidades/TratamientoErrores'
import { ErrorGeneral } from '../../componentes/ErrorGeneral/ErrorGeneral';
import { MensajeInformativo } from '../../componentes/MensajeInformativo/MensajeInformativo';

import { Button,  Grid, TextField, Typography } from '@mui/material';
import { ActualizarRecurso, CrearRecurso, LeerRecurso } from '../../servicios/RQRecursos';
import { UploadDataS3 } from '../../servicios/AwsLib'
import { ConsultarParametrosPorId, } from '../../servicios/RQParametros'


export const RecursoPagina = () => {
    const params = useParams()
    const navigate = useNavigate()
    const { getSession } = useContext(GeneralCtx)
    const [hayError, setHayError] = useState(false)
    const [mensajeError, setMensajeError] = useState('')
    const [hayMensaje, setHayMensaje] = useState(false)
    const [mensaje, setMensaje] = useState('')
    const [parametros, setParametros] = useState({})
    

    const handleSubmit = async (values) => {
        values.empresaId = session.empresa.empresaId
        if (!values.recursoId) {
            await crearRecurso.mutateAsync(values)
        } else {
            await actualizarRecurso.mutateAsync(values)
        }
        navigate('/recursos')
    }
    const formik = useFormik({
        initialValues: initialValues(),
        validationSchema: validationSchema(),
        onSubmit: handleSubmit,
    });

    const salirForm = (e) => {
        if (e) e.preventDefault()
        navigate('/recursos')
    }

    const actualizarRecurso = useMutation((recurso) => { return ActualizarRecurso(recurso) }, {
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })

    const crearRecurso = useMutation((recurso) => { return CrearRecurso(recurso) }, {
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })

    const session = getSession()
    useQuery(['recurso', params.recursoId], () => { return LeerRecurso(params.recursoId, session.empresa.empresaId) }, {
        onSuccess: (data, variables, context) => {
            formik.setValues({ ...formik.values, ...data.data })
        },
        onError: (error, variables, context) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        },
        enabled: params.recursoId !== '0'
    })

    useQuery('parametros', () => { return ConsultarParametrosPorId(0, session.empresa) }, {
        onSuccess: (data, variables, context) => {
            setParametros(data.data)
        },
        onError: (error, variables, context) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })

    useEffect(() => {
        formik.setFieldValue('empresaId', session.empresa.empresaId)
    }, [])


    async function getFile() {
        var files = document.getElementById("fileupload").files;
        if (!files.length) {
            alert('Debe escoger seleccionar un archivo para subirlo al repositorio');
            return;
        }
        var file = files[0];
        var l = file.name.split('.');
        var index = l.length - 1;
        var ext = l[index]
        var name =  formik.values.nombre + "." + ext;
        var fileKey = parametros.bucket_folder + "/" + name;
        var params = {
            Bucket: parametros.bucket,
            Key: fileKey,
            IdentityPoolId: parametros.identity_pool,
            Body: file,
            ACL: "public-read"
        }
        let location = await UploadDataS3(parametros.bucket_region, parametros.identity_pool, params);
        formik.setFieldValue('url', location);
    }


    return (
        <>
            <MenuLateral>
                <form onSubmit={formik.handleSubmit}>
                    <Grid container spacing={2}>
                        <Grid item xs={6}>
                            <Typography variant='h6'>Datos de recurso:</Typography>
                        </Grid>
                        <Grid item xs={6} sx={{ textAlign: 'right' }}>
                            <Button color="success" variant="contained" onClick={salirForm}>
                                Salir
                            </Button>
                            <Button color="primary" variant="contained" type="submit" sx={{ marginLeft: 2 }}>
                                Aceptar
                            </Button>
                        </Grid>
                        <Grid item xs={2} md={2}>
                            <TextField fullWidth id="recursoId" name="recursoId" label="ID" disabled
                                value={formik.values.recursoId}
                                onChange={formik.handleChange}
                                error={formik.touched.recursoId && Boolean(formik.errors.recursoId)}
                                helperText={formik.touched.recursoId && formik.errors.recursoId}
                            />
                        </Grid>
                        <Grid item xs={10} md={10}>
                            <TextField fullWidth id="nombre" name="nombre" label="Nombre"
                                value={formik.values.nombre}
                                onChange={formik.handleChange}
                                error={formik.touched.nombre && Boolean(formik.errors.nombre)}
                                helperText={formik.touched.nombre && formik.errors.nombre}
                            />
                        </Grid>
                        <Grid item xs={10} md={10}>
                            <TextField fullWidth id="url" name="url" label="URL"
                                value={formik.values.url}
                                onChange={formik.handleChange}
                                error={formik.touched.url && Boolean(formik.errors.url)}
                                helperText={formik.touched.url && formik.errors.url}
                            />
                        </Grid>
                        <Grid style={{marginTop: 1+'%'}}item xs={2} md={2}>
                            <Button
                                variant="contained"
                                component="label"
                            > Upload File
                                <input
                                    id="fileupload"
                                    type="file"
                                    onChange={getFile}
                                    hidden
                                />
                            </Button>
                        </Grid>
                        <Grid item xs={12} md={6}>
                        </Grid>
                        <Grid item xs={12} sx={{ textAlign: 'right' }}>
                            <Button color="success" variant="contained" onClick={salirForm}>
                                Salir
                            </Button>
                            <Button color="primary" variant="contained" type="submit" sx={{ marginLeft: 2 }}>
                                Aceptar
                            </Button>
                        </Grid>
                    </Grid>
                </form>
                <ErrorGeneral hayError={hayError} mensajeError={mensajeError} cerrarError={() => setHayError(false)} />
                <MensajeInformativo hayMensaje={hayMensaje} mensaje={mensaje} cerrarMensaje={() => setHayMensaje(false)} />
            </MenuLateral>
        </>
    )
}
