import React, { useContext, useState } from 'react'
import { useParams } from 'react-router-dom'
import { MenuLateral } from '../../componentes/MenuLateral/MenuLateral'
import { useFormik } from 'formik';
import { useMutation, useQuery } from "react-query";
import { initialValues, validationSchema } from './ClienteFunciones'
import { useNavigate } from 'react-router-dom';
import { GeneralCtx } from '../../contextos/GeneralContext'
import { MensajeError } from '../../utilidades/TratamientoErrores'
import { ErrorGeneral } from '../../componentes/ErrorGeneral/ErrorGeneral';
import { DateTimePicker, LocalizationProvider } from '@mui/x-date-pickers';
import { AdapterMoment } from '@mui/x-date-pickers/AdapterMoment';
import { ConvertirAFechaEs } from '../../utilidades/TratamienfoFechas';

import 'moment/locale/es'

import { Button, Grid, TextField, Typography } from '@mui/material';
import { ActualizarCliente, CrearCliente, LeerCliente } from '../../servicios/RQClientes';


export const ClientePagina = () => {
    const params = useParams()
    const navigate = useNavigate()
    const { getSession } = useContext(GeneralCtx)
    const [hayError, setHayError] = useState(false)
    const [mensajeError, setMensajeError] = useState('')
   
    const [selectedDateAlt, setSelectedDateAlt] = useState(null);
    const [selectedDateBaj, setSelectedDateBaj] = useState(null);

    const handleSubmit = async (values) => {
        if (!values.codclien) {
            await crearCliente.mutateAsync(values)
        } else {
            await actualizarCliente.mutateAsync(values)
        }
        setSelectedDateAlt(values.fechaalt)
        //values.fechaalt = moment(selectedDate).format('YYYY-MM-DD HH:mm:ss')
        navigate('/clientes')
    }
    const formik = useFormik({
        initialValues: initialValues(),
        validationSchema: validationSchema(),
        onSubmit: handleSubmit,
    });

    const salirForm = (e) => {
        if (e) e.preventDefault()
        navigate('/clientes')
    }

    const actualizarCliente = useMutation((cliente) => { return ActualizarCliente(cliente, session.empresa.empresaId) }, {
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })

    const crearCliente = useMutation((cliente) => { return CrearCliente(cliente) }, {
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })

    const session = getSession()
    useQuery(['cliente', params.codclien], () => { return LeerCliente(params.codclien, session.empresa.empresaId) }, {
        onSuccess: (data, variables, context) => {
            //setSelectedDate(moment(data.data.fechaalt).format('DD-MM-YYYY HH:mm:ss'));
            //data.data.fechaalt = moment(data.data.fechaalt).format('DD-MM-YYYY HH:mm:ss')
            formik.setValues({ ...formik.values, ...data.data })
            setSelectedDateAlt(ConvertirAFechaEs(data.data.fechaalt));
            setSelectedDateBaj(ConvertirAFechaEs(data.data.fechabaj));
        },
        onError: (error, variables, context) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        },
        enabled: params.codclien !== '0'
    })


    return (
        <>
            <MenuLateral>
                <form onSubmit={formik.handleSubmit}>
                    <Grid container spacing={2}>
                        <Grid item xs={6}>
                            <Typography variant='h6'>Datos de cliente:</Typography>
                        </Grid>
                        <Grid item xs={6} sx={{ textAlign: 'right' }}>
                            <Button color="success" variant="contained" onClick={salirForm}>
                                Salir
                            </Button>
                            <Button color="primary" variant="contained" type="submit" sx={{ marginLeft: 2 }}>
                                Aceptar
                            </Button>
                        </Grid>
                        <Grid item xs={2}>
                            <TextField fullWidth id="codclien" name="codclien" label="ID" disabled
                                value={formik.values.codclien ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.codclien && Boolean(formik.errors.codclien)}
                                helperText={formik.touched.codclien && formik.errors.codclien}
                            />
                        </Grid>
                        <Grid item xs={10}>
                            <TextField fullWidth id="nomclien" name="nomclien" label="Nombre" disabled
                                value={formik.values.nomclien ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.nomclien && Boolean(formik.errors.nomclien)}
                                helperText={formik.touched.nomclien && formik.errors.nomclien}
                            />
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <TextField fullWidth id="domclien" name="domclien" label="Domicilio" disabled
                                value={formik.values.domclien ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.domclien && Boolean(formik.errors.domclien)}
                                helperText={formik.touched.domclien && formik.errors.domclien}
                            />
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <TextField fullWidth id="pobclien" name="pobclien" label="Población" disabled
                                value={formik.values.pobclien ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.pobclien && Boolean(formik.errors.pobclien)}
                                helperText={formik.touched.pobclien && formik.errors.pobclien}
                            />
                        </Grid>
                        <Grid item xs={10} md={2}>
                            <TextField fullWidth id="proclien" name="proclien" label="Provincia" disabled
                                value={formik.values.proclien ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.proclien && Boolean(formik.errors.proclien)}
                                helperText={formik.touched.proclien && formik.errors.proclien}
                            />
                        </Grid>
                        <Grid item xs={2} md={2}>
                            <TextField fullWidth id="nifclien" name="nifclien" label="NIF" disabled
                                value={formik.values.nifclien ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.nifclien && Boolean(formik.errors.nifclien)}
                                helperText={formik.touched.nifclien && formik.errors.nifclien}
                            />
                        </Grid>
                        <Grid item xs={12} md={6}>
                            <TextField fullWidth id="iban" name="iban" label="IBAN" disabled
                                value={formik.values.iban ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.iban && Boolean(formik.errors.iban)}
                                helperText={formik.touched.iban && formik.errors.iban}
                            />
                        </Grid>
                        <Grid item xs={6} md={3}>
                            <LocalizationProvider dateAdapter={AdapterMoment} adapterLocale="es-ES">
                                <DateTimePicker
                                    disabled
                                     renderInput={(props) => <TextField {...props} />}
                                     label="Fecha alta"
                                     value={selectedDateAlt}
                                     onChange={(newValue) => {
                                         setSelectedDateAlt(newValue);
                                     }}
                                />
                            </LocalizationProvider>
                        </Grid>
                        
                        <Grid item xs={6} md={3}>
                            <LocalizationProvider dateAdapter={AdapterMoment} adapterLocale="es-ES">
                                <DateTimePicker
                                     disabled
                                     renderInput={(props) => <TextField {...props} />}
                                     label="Fecha baja"
                                     value={selectedDateBaj}
                                     onChange={(newValue) => {
                                         setSelectedDateBaj(newValue);
                                     }}
                                />
                            </LocalizationProvider>
                        </Grid>

                        <Grid item xs={12} md={4}>
                            <TextField fullWidth id="login" name="login" label="Login" 
                                value={formik.values.login ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.login && Boolean(formik.errors.login)}
                                helperText={formik.touched.login && formik.errors.login}
                            />
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <TextField fullWidth id="password" name="password" label="Contraseña"
                                type='password'
                                value={formik.values.password ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.password && Boolean(formik.errors.password)}
                                helperText={formik.touched.password && formik.errors.password}
                            />
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <TextField fullWidth id="playerId" name="playerId" label="PlayerId" disabled
                                value={formik.values.playerId ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.playerId && Boolean(formik.errors.playerId)}
                                helperText={formik.touched.playerId && formik.errors.playerId}
                            />
                        </Grid>

                        <Grid item xs={12} md={4}>
                            <TextField fullWidth id="telclie1" name="telclie1" label="Teléfono" disabled
                                value={formik.values.telclie1 ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.telclie1 && Boolean(formik.errors.telclie1)}
                                helperText={formik.touched.telclie1 && formik.errors.telclie1}
                            />
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <TextField fullWidth id="movclien" name="movclien" label="Movil" disabled
                                value={formik.values.movclien ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.movclien && Boolean(formik.errors.movclien)}
                                helperText={formik.touched.movclien && formik.errors.movclien}
                            />
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <TextField fullWidth id="maiclie1:" name="maiclie1:" label="Correo" disabled
                                value={formik.values.maiclie1 ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.maiclie1 && Boolean(formik.errors.maiclie1)}
                                helperText={formik.touched.maiclie1 && formik.errors.maiclie1}
                            />
                        </Grid>

                        <Grid item xs={12} md={6}>
                        </Grid>
                        <Grid item xs={12} sx={{ textAlign: 'right' }}>
                            <Button color="success" variant="contained" onClick={salirForm}>
                                Salir
                            </Button>
                            <Button color="primary" variant="contained" type="submit" sx={{ marginLeft: 2 }}>
                                Aceptar
                            </Button>
                        </Grid>
                    </Grid>
                </form>
                <ErrorGeneral hayError={hayError} mensajeError={mensajeError} cerrarError={() => setHayError(false)} />
            </MenuLateral>
        </>
    )
}
