import AWS from 'aws-sdk'


export const UploadDataS3 = async (awsRegion, awsCognitoPoolId, params) => {
    AWS.config.update({
        region: awsRegion,
        credentials: new AWS.CognitoIdentityCredentials({
            IdentityPoolId: awsCognitoPoolId
        })
    });
    
    var upload = new AWS.S3.ManagedUpload({
        params
    });
    let respuesta = await upload.promise();
    return respuesta.Location
}

export const CopiarDataS3 = async (awsRegion, awsBucket, awsCognitoPoolId, awsKey, awsKey2) => {
    AWS.config.update({
        region: awsRegion,
        credentials: new AWS.CognitoIdentityCredentials({
            IdentityPoolId: awsCognitoPoolId
        })
    });
    const url_origen = `https://${awsBucket}.s3.${awsRegion}.amazonaws.com/${awsKey}`
    const response = await fetch(url_origen);
    const data = await response.blob();
    let params = {
        Bucket: awsBucket,
        Key: awsKey2,
        Body: data,
        ContentEncoding: 'base64',
        ContentType: 'image/jpeg',
        ACL: "public-read"
    };
    var upload = new AWS.S3.ManagedUpload({
        params
    });
    let respuesta = await upload.promise();
    return respuesta.Location
}


