import React, { useContext, useState } from 'react'
import { MenuLateral } from '../../componentes/MenuLateral/MenuLateral'
import { useFormik } from 'formik';
import { useMutation, useQuery } from "react-query";
import { initialValues, validationSchema } from './ParametrosFunciones'
import { Button, Grid, TextField, Typography } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import { GeneralCtx } from '../../contextos/GeneralContext'
import { ActualizarParametros, ConsultarParametrosPorId, } from '../../servicios/RQParametros'
import { MensajeError } from '../../utilidades/TratamientoErrores'
import { ErrorGeneral } from '../../componentes/ErrorGeneral/ErrorGeneral';
import { MensajeInformativo } from '../../componentes/MensajeInformativo/MensajeInformativo';


export const ParametrosPagina = () => {
    const navigate = useNavigate()
    const { getSession } = useContext(GeneralCtx)
    const [hayError, setHayError] = useState(false)
    const [mensajeError, setMensajeError] = useState('')
    const [hayMensaje, setHayMensaje] = useState(false)
    const [mensaje, setMensaje] = useState('')

    const handleSubmit = async (values) => {
        let r = await updateParametros.mutateAsync(values);
        if(r) {
            setMensaje('Los datos han sido guardados correctamente');
            setHayMensaje(true);
           
            setTimeout(() => {
                navigate(-1);
              }, "1000");
              
        }
    }
    const formik = useFormik({
        initialValues: initialValues(),
        validationSchema: validationSchema(),
        onSubmit: handleSubmit,
    });

    const salirForm = (e) => {
        if (e) e.preventDefault()
        navigate(-1)
    }

    const session = getSession()
    useQuery('parametros', () => { return ConsultarParametrosPorId(0, session.empresa) }, {
        onSuccess: (data, variables, context) => {
            formik.setValues({ ...formik.values, ...data.data })
        },
        onError: (error, variables, context) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })
    const updateParametros = useMutation((parametros) => { return ActualizarParametros(parametros, session.empresa.empresaId,) }, {
        onSuccess: (data, variables, context) => {
            return data;
        },
        onError: (error, variables, context) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })

    return (
        <>
            <MenuLateral>
                <form onSubmit={formik.handleSubmit}>
                    <Grid container spacing={2}>
                        <Grid item xs={12}>
                            <Typography variant='h6'>Datos de los parámetros:</Typography>
                        </Grid>
                        <Grid item xs={2}>
                            <TextField fullWidth id="parametroId" name="parametroId" label="ID" disabled
                                value={formik.values.parametroId}
                                onChange={formik.handleChange}
                                error={formik.touched.parametroId && Boolean(formik.errors.parametroId)}
                                helperText={formik.touched.parametroId && formik.errors.parametroId}
                            />
                        </Grid>
                        <Grid item xs={10}>
                            <TextField fullWidth id="tituloPush" name="tituloPush" label="Titulo para las notificaciones"
                                value={formik.values.tituloPush}
                                onChange={formik.handleChange}
                                error={formik.touched.tituloPush && Boolean(formik.errors.tituloPush)}
                                helperText={formik.touched.tituloPush && formik.errors.tituloPush}
                            />
                        </Grid>
                        <Grid item xs={12} md={4}>
                            <TextField fullWidth id="appId" name="appId" label="Clave de la app (appId)"
                                value={formik.values.appId}
                                onChange={formik.handleChange}
                                error={formik.touched.appId && Boolean(formik.errors.appId)}
                                helperText={formik.touched.appId && formik.errors.appId}
                            />
                        </Grid>
                        <Grid item xs={10} md={5}>
                            <TextField fullWidth id="restApi" name="restApi" label="Clave rest (restApi)"
                                value={formik.values.restApi}
                                onChange={formik.handleChange}
                                error={formik.touched.restApi && Boolean(formik.errors.restApi)}
                                helperText={formik.touched.restApi && formik.errors.restApi}
                            />
                        </Grid>
                        <Grid item xs={2} md={3}>
                            <TextField fullWidth id="gcm" name="gcm" label="GCM"
                                value={formik.values.gcm}
                                onChange={formik.handleChange}
                                error={formik.touched.gcm && Boolean(formik.errors.gcm)}
                                helperText={formik.touched.gcm && formik.errors.gcm}
                            />
                        </Grid>
                        <Grid item xs={12} sx={{ textAlign: 'right' }}>
                            <Button color="success" variant="contained" onClick={salirForm}>
                                Salir
                            </Button>
                            {/* <Button color="primary" variant="contained" type="submit" sx={{ marginLeft: 2 }}>
                                Aceptar
                            </Button> */}
                        </Grid>
                    </Grid>
                </form>
                <ErrorGeneral hayError={hayError} mensajeError={mensajeError} cerrarError={() => setHayError(false)} />
                <MensajeInformativo hayMensaje={hayMensaje} mensaje={mensaje} cerrarMensaje={() => setHayMensaje(false)} />
            </MenuLateral>
        </>
    )
}
