import * as yup from 'yup';

export const initialValues = () => {
    return {
        mensajeId: 0,
        asunto: '',
        texto: '',
        usuPush: [],
        fichero: "",
        necesitaConfirmacion: false,
        administradorId: 0
    }
}

export const validationSchema = () => {
    return yup.object({
        asunto: yup.string().required('Requerido'),
        texto: yup.string().required('Requerido'),
        //usuPush: yup.array().min(1, 'Al menos un usuario debe ser seleccionado'),
    })
}