import { Grid, IconButton, Paper, Typography } from '@mui/material'
import React from 'react'
import { MenuLateral } from '../../componentes/MenuLateral/MenuLateral'
import MenuIcon from '@mui/icons-material/Menu';

export const InicioPagina = () => {
  return (
    <>
      <MenuLateral>
        <Grid container spacing={2} className="fondoImagen">
          <Grid item xs={12}>
              <Typography  variant='h3'> ARITAXI NOTIFICACIONES </Typography>
              <Typography>
                Bienvenido a la aplicación. Para acceder a las diferentes funciones puede hacer uso del menú de parte lateral. Intentando conseguir el
                máximo espacio de trabajo, ese menú está oculto por defecto, puede desplegarlo y ocultarlo haciendo clic en el icono <IconButton color="primary"><MenuIcon /></IconButton> de la parte superior izquierda
                de la barra de tareas.
              </Typography>
            
          </Grid>
        </Grid>
      </MenuLateral>
    </>

  )
}
