import axios from 'axios'
import Entorno from './Entorno'


export const LoginBasicoAdministrador = (data) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/usuarios/login`
    const body = {
        usuario: {
            empresaId: data.empresaId,
            login: data.login,
            password: data.password
        }
       
    }
    return axios.post(url, body)
}

export const LeerUsuarios = (empresaId) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/usuarios/${empresaId}`
    return axios.get(url)
}

export const CrearAdministrador = (administrador) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/administradores`
    return axios.post(url, administrador)
}

export const ActualizarAdministrador = (administrador) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/administradores`
    return axios.put(url, administrador)
}

export const LeerAdministrador = (empresaId, administradorId) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/administradores/empresa/${empresaId}/${administradorId}`
    return axios.get(url)
}

export const eliminarAdministrador = (empresaId, administradorId) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/administradores/empresa/${empresaId}/${administradorId}`
    return axios.delete(url)
}