import { Grid, Typography } from '@mui/material'
import React, { useEffect, useState } from 'react'
import { leerVersion } from '../../servicios/ApiLib'
import { LoginForm } from './LoginForm'
import './LoginPagina.css'
import { ConsultarParametrosPorId } from '../../servicios/RQParametros'

export const LoginPagina = () => {
    const [version, setVersion] = useState('0.0.0')
    const [empresa, setEmpresa] = useState({
        accUrl: "localhost",
        accLogo: "https://tdinf-uploads.s3.eu-west-1.amazonaws.com/ariadna/Ariadna_140.png",
        nombre: 'AriTaxiPush'
    })
    const [nombre, setNombre] = useState('ARITAXI')
    const consultarVersion = async () => {
        const { data: versionData } = await leerVersion()
        setVersion(versionData.version)
        
        const { data: parametros } = await ConsultarParametrosPorId(0, 0)
        setNombre(parametros.tituloPush)
    }


    useEffect(() => {
        consultarVersion()
        //consultarAcceso()
    }, [])


    return (
        <>
            <Grid container>
                <Grid item xs={8} className="fondoImagenLogin">
                    <Typography variant='h3'>
                        AriTaxiPush
                    </Typography>
                    <Typography variant='h6'>
                        Gestión de notificaciones
                    </Typography>
                    <Typography>
                        {version}
                    </Typography>
                </Grid>
                <Grid item xs={4} className="loginForm">
                    <div className='recuadro'>
                        <LoginForm dtLogin={empresa} nombre={nombre} />
                    </div>
                </Grid>
            </Grid>
        </>
    )
}
