import React, { useContext, useEffect, useState } from 'react'
import { useParams } from 'react-router-dom'
import { MenuLateral } from '../../componentes/MenuLateral/MenuLateral'
import { useFormik } from 'formik';
import { useMutation, useQuery } from "react-query";
import { initialValues, validationSchema } from './EnlacesFunciones'
import { useNavigate } from 'react-router-dom';
import { GeneralCtx } from '../../contextos/GeneralContext'
import { MensajeError } from '../../utilidades/TratamientoErrores'
import { ErrorGeneral } from '../../componentes/ErrorGeneral/ErrorGeneral';
import { MensajeInformativo } from '../../componentes/MensajeInformativo/MensajeInformativo';

import { Button, Grid, TextField, Typography } from '@mui/material';
import { ActualizarEnlace, CrearEnlace, LeerEnlace } from '../../servicios/RQEnlaces';


export const EnlacePagina = () => {
    const params = useParams()
    const navigate = useNavigate()
    const { getSession } = useContext(GeneralCtx)
    const [hayError, setHayError] = useState(false)
    const [mensajeError, setMensajeError] = useState('')
    const [hayMensaje, setHayMensaje] = useState(false)
    const [mensaje, setMensaje] = useState('')
    

    const handleSubmit = async (values) => {
        values.empresaId = session.empresa.empresaId;
        if (!values.enlaceId) {
            await crearEnlace.mutateAsync(values)
        } else {
            await actualizarEnlace.mutateAsync(values)
        }
        navigate('/enlaces')
    }
    const formik = useFormik({
        initialValues: initialValues(),
        validationSchema: validationSchema(),
        onSubmit: handleSubmit,
    });

    const salirForm = (e) => {
        if (e) e.preventDefault()
        navigate('/enlaces')
    }

    const actualizarEnlace = useMutation((enlace) => { return ActualizarEnlace(enlace) }, {
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })

    const crearEnlace = useMutation((enlace) => { return CrearEnlace(enlace) }, {
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })

    const session = getSession()
    useQuery(['enlace', params.enlaceId], () => { return LeerEnlace(params.enlaceId, session.empresa.empresaId) }, {
        onSuccess: (data, variables, context) => {
            //setSelectedDate(moment(data.data.fechaalt).format('DD-MM-YYYY HH:mm:ss'));
            //data.data.fechaalt = moment(data.data.fechaalt).format('DD-MM-YYYY HH:mm:ss')
            formik.setValues({ ...formik.values, ...data.data })
        },
        onError: (error, variables, context) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        },
        enabled: params.enlaceId !== '0'
    })

    useEffect(() => {
        formik.setFieldValue('empresaId', session.empresa.empresaId)
    }, [])


    return (
        <>
            <MenuLateral>
                <form onSubmit={formik.handleSubmit}>
                    <Grid container spacing={2}>
                        <Grid item xs={6}>
                            <Typography variant='h6'>Datos de enlace:</Typography>
                        </Grid>
                        <Grid item xs={6} sx={{ textAlign: 'right' }}>
                            <Button color="success" variant="contained" onClick={salirForm}>
                                Salir
                            </Button>
                            <Button color="primary" variant="contained" type="submit" sx={{ marginLeft: 2 }}>
                                Aceptar
                            </Button>
                        </Grid>
                        <Grid item xs={2} md={2}>
                            <TextField fullWidth id="enlaceId" name="enlaceId" label="ID" disabled
                                value={formik.values.enlaceId ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.enlaceId && Boolean(formik.errors.enlaceId)}
                                helperText={formik.touched.enlaceId && formik.errors.enlaceId}
                            />
                        </Grid>
                        <Grid item xs={10} md={4}>
                            <TextField fullWidth id="nombre" name="nombre" label="Nombre"
                                value={formik.values.nombre ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.nombre && Boolean(formik.errors.nombre)}
                                helperText={formik.touched.nombre && formik.errors.nombre}
                            />
                        </Grid>
                        <Grid item xs={12} md={6}>
                            <TextField fullWidth id="url" name="url" label="URL"
                                value={formik.values.url ?? ''}
                                onChange={formik.handleChange}
                                error={formik.touched.url && Boolean(formik.errors.url)}
                                helperText={formik.touched.url && formik.errors.url}
                            />
                        </Grid>
                        <Grid item xs={12} md={6}>
                        </Grid>
                        <Grid item xs={12} sx={{ textAlign: 'right' }}>
                            <Button color="success" variant="contained" onClick={salirForm}>
                                Salir
                            </Button>
                            <Button color="primary" variant="contained" type="submit" sx={{ marginLeft: 2 }}>
                                Aceptar
                            </Button>
                        </Grid>
                    </Grid>
                </form>
                <ErrorGeneral hayError={hayError} mensajeError={mensajeError} cerrarError={() => setHayError(false)} />
                <MensajeInformativo hayMensaje={hayMensaje} mensaje={mensaje} cerrarMensaje={() => setHayMensaje(false)} />
            </MenuLateral>
        </>
    )
}
