import axios from 'axios'
import Entorno from './Entorno'




export const LeerClientes = (estado, empresaId) => {
    let id = estado.id;
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    let url = `${url_base}/api/clientes/${empresaId}`
    if(id === 1) {
        url = `${url_base}/api/clientes/logados/${empresaId}`
    } else if(id === 2) {
        url = `${url_base}/api/clientes/sin-logar/usuarios/${empresaId}`
    }
    
    return axios.get(url)
}

export const CrearCliente = (cliente) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/clientes`
    return axios.post(url, cliente)
}

export const ActualizarCliente = (cliente, empresaId) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/clientes/${cliente.codclien}/${empresaId}`
    return axios.put(url,{ cliente: cliente })
}

export const LeerCliente = (codclien, empresaId) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/clientes/${codclien}/${empresaId}`
    return axios.get(url)
}

export const eliminarCliente = (empresaId, codclien) => {
    const ent = Entorno.gentEnv()
    const url_base = ent.API_URL
    const url = `${url_base}/api/clientes/empresa/${empresaId}/${codclien}`
    return axios.delete(url)
}