import { AppBar, Grid, IconButton, Toolbar, Tooltip, Typography} from '@mui/material'
import React, { useContext, useState } from 'react'
import { useMutation, useQuery } from 'react-query'
import { useNavigate } from 'react-router-dom'
import { MenuLateral } from '../../componentes/MenuLateral/MenuLateral'
import { MensajeError } from '../../utilidades/TratamientoErrores'
import { ErrorGeneral } from '../../componentes/ErrorGeneral/ErrorGeneral';
import { LeerMensajes, EliminarMensaje } from '../../servicios/RQMensajes'
import { GeneralCtx } from '../../contextos/GeneralContext'
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import { FormatoFechaEs } from "../../utilidades/TratamienfoFechas";
import { MensajeConfirmacion } from '../../componentes/MensajeConfirmacion/MensajeConfirmacion'
import { MensajeInformativo } from '../../componentes/MensajeInformativo/MensajeInformativo'
import { DataGrid, esES, GridToolbar } from '@mui/x-data-grid';

export const MensajesPagina = (props) => {
    const navigate = useNavigate()
    const { getSession } = useContext(GeneralCtx)
    const [hayError, setHayError] = useState(false)
    const [mensajeError, setMensajeError] = useState('');
    const [mensajeInsormativo, setmensajeInformativo] = useState('')
    const [hayMensaje, setHayMensaje] = useState(false)
    const [mensaje, setMensaje] = useState('')
    const [hayConfirmacion, setHayConfirmacion] = useState(false)
    const [mensajeConfirmacion, setMensajeConfirmacion] = useState('')
    const [mensajes, setMensajes] = useState([])
     
    
    const session = getSession()
    const queryUsuarios = useQuery('mensajes', () => { return LeerMensajes(session.empresa.empresaId) }, {
        onSuccess: (data) => {
            setMensajes(data.data)
        },
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })
    const eliminaMensaje = useMutation(({ empresaId, mensajeId }) => { return EliminarMensaje(empresaId, mensajeId) }, {
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })


    const newMensaje = () => {
        navigate(`/mensaje/0`)
    }

    const editMensaje = (id) => {
        return () => {
            navigate(`/mensaje/${id}`)
        }
    }



    const deleteMensaje = (row) => {
        return () => {
            setMensaje(row)
            setMensajeConfirmacion(`¿Realmente desea eliminar el mensaje ${row.asunto}?`)
            setHayConfirmacion(true)
        }
    }

    const deleteConfirmado = async () => {
        await eliminaMensaje.mutateAsync({ empresaId: session.empresa.empresaId, mensajeId: mensaje.mensajeId })
        queryUsuarios.refetch()
        setHayConfirmacion(false)
        setmensajeInformativo(`El mensaje ${mensaje.asunto} ha sido eliminado de la base de datos`)
        setHayMensaje(true)
    }

    const columns = [
        { field: 'mensajeId', headerName: 'ID' },
        { field: 'fecha', headerName: 'Fecha',  type: 'date', width: 180,
        valueFormatter: params =>
            FormatoFechaEs(params.value),},
        { field: 'asunto', headerName: 'Asunto', flex: 1 },
        { field: 'estado', headerName: 'Estado' },
        { field: 'responsable', headerName: 'Responsable' },
        {
            field: 'actions',
            type: 'actions',
            headerName: 'Acciones',
           
            flex: 0.5,
            getActions: ({row}) => {
                return [<IconButton onClick={deleteMensaje(row)}>
                    <DeleteIcon />
                </IconButton>,
                <IconButton onClick={editMensaje(row.mensajeId)}>
                    <EditIcon />
                </IconButton>
                ]
            }
        },
    ]

    return (
        <>
            <MenuLateral>
                <Grid container spacing={2}>
                    <Grid item xs={12}>
                        <AppBar id="imagen" position='static' color='secondary'>
                            <Toolbar>
                                <Typography variant='h6' component='h6'>
                                    Mensajes
                                </Typography>
                                <span className='toolbarButtons'>
                                    <IconButton size="large" aria-label="Nuevo mensaje" color="inherit" onClick={newMensaje}>
                                        <Tooltip title="Nuevo mensaje" >
                                            <AddIcon />
                                        </Tooltip>
                                    </IconButton>
                                </span>
                            </Toolbar>
                        </AppBar>
                    </Grid>
                    
                    <Grid item xs={12} style={{ height: '80vh', width: '100%' }}>
                        <DataGrid rows={mensajes} columns={columns} getRowId={(row) => row.mensajeId} components={{Toolbar: GridToolbar}}
                            localeText={esES.components.MuiDataGrid.defaultProps.localeText} />
                    </Grid>
                </Grid>
                <ErrorGeneral hayError={hayError} mensajeError={mensajeError} cerrarError={() => setHayError(false)} />
                <MensajeInformativo hayMensaje={hayMensaje} mensaje={mensajeInsormativo} cerrarMensaje={() => setHayMensaje(false)} />
                <MensajeConfirmacion hayConfirmacion={hayConfirmacion} mensaje={mensajeConfirmacion} confirmar={deleteConfirmado} cerrarConfirmacion={() => setHayConfirmacion(false)} />
            </MenuLateral>
        </>

    )
}
