import React, { useContext, useEffect, useState } from 'react';
import Box from '@mui/material/Box';
import Drawer from '@mui/material/Drawer';
import AppBar from '@mui/material/AppBar';
import CssBaseline from '@mui/material/CssBaseline';
import Toolbar from '@mui/material/Toolbar';
import List from '@mui/material/List';
import Typography from '@mui/material/Typography';
import ListItem from '@mui/material/ListItem';
import ListItemButton from '@mui/material/ListItemButton';
import ListItemIcon from '@mui/material/ListItemIcon';
import CloudQueueIcon from '@mui/icons-material/CloudQueue';
import RocketLaunchIcon from '@mui/icons-material/RocketLaunch';
import { Collapse, Divider, Grid, IconButton, ListItemText } from '@mui/material';
import MenuIcon from '@mui/icons-material/Menu';
import { ExpandLess, ExpandMore, Home } from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import ExitToAppIcon from '@mui/icons-material/ExitToApp';
import QuestionAnswerRoundedIcon from '@mui/icons-material/QuestionAnswerRounded';
import PeopleIcon from '@mui/icons-material/People';
import PersonIcon from '@mui/icons-material/Person';
import LocalTaxiIcon from '@mui/icons-material/LocalTaxi';
import LinkIcon from '@mui/icons-material/Link';
import WidgetsIcon from '@mui/icons-material/Widgets';
import ApartmentIcon from '@mui/icons-material/Apartment';

import { GeneralCtx } from '../../contextos/GeneralContext'

const drawerWidth = 230;

export const MenuLateral = (props) => {
    const [openSubmenuAdministracion, setOpenSubmenuAdministracion] = useState(false);
    const [openSubmenuMensajes, setOpenSubmenuMensajes] = useState(false);
    const { getSession } = useContext(GeneralCtx)
    const navigate = useNavigate()
    const [sesion, setSesion] = useState()
    const [drVariant, setDrVariant] = useState('temporary')
    const [drOpen, setDrOpen] = useState(false)
    const handleDrOpen = () => {
        if (drOpen) {
            // ya está abierto y lo cerramos
            setDrVariant('temporary')
            setDrOpen(false)
        } else {
            // no está abierto, lo abrimos
            setDrVariant('permanent')
            setDrOpen(true)
        }
    }

    const handleClose = () => {
        navigate('/')
    }

    useEffect(() => {
        // Comprobación de que hay una sesión activa
        let session = getSession()
        if (!session) navigate('/')
        setSesion(session)
    }, [])

    return (
        <div>
            <Box sx={{ display: 'flex' }}>
                <CssBaseline />
                <Grid container>
                    <Grid item xs={12}>
                        <AppBar position="fixed" sx={{ zIndex: (theme) => theme.zIndex.drawer + 1 }}>
                            <Toolbar>
                                <IconButton
                                    size="large"
                                    edge="start"
                                    color="inherit"
                                    aria-label="menu"
                                    sx={{ mr: 2 }}
                                    onClick={handleDrOpen}
                                >
                                    <MenuIcon />
                                </IconButton>
                                <Typography variant="h6" noWrap component="div" sx={{ flexGrow: 1 }}>
                                    Aritaxi notificaciones
                                </Typography>
                                <IconButton
                                    size="large"
                                    edge="start"
                                    color="inherit"
                                    aria-label="menu"
                                >
                                    <PersonIcon />
                                    <Typography ml={1}>{sesion ? sesion.administrador.nombre : ''}</Typography>
                                </IconButton>
                                <IconButton
                                    size="large"
                                    edge="start"
                                    color="inherit"
                                    aria-label="menu"
                                    onClick={handleClose}
                                >
                                    <ExitToAppIcon />
                                </IconButton>
                            </Toolbar>
                        </AppBar>
                        <Drawer
                            variant={drVariant}
                            sx={{
                                width: drawerWidth,
                                flexShrink: 0,
                                [`& .MuiDrawer-paper`]: { width: drawerWidth, boxSizing: 'border-box' },
                            }}
                            open={drOpen}
                        >
                            <Toolbar />
                            <Box sx={{ overflow: 'auto' }}>
                                <List>
                                    <ListItem key='Inicio' disablePadding onClick={() => { navigate('/inicio') }}>
                                        <ListItemButton>
                                            <ListItemIcon>
                                                <Home />
                                            </ListItemIcon>
                                            <ListItemText> Inicio </ListItemText>
                                        </ListItemButton>
                                    </ListItem>
                                </List>
                                <Divider />

                                <List>
                                    <ListItem key='Administracion' disablePadding onClick={() => { setOpenSubmenuAdministracion(!openSubmenuAdministracion) }}>
                                        <ListItemButton>
                                            <ListItemIcon>
                                                <ApartmentIcon />
                                            </ListItemIcon>
                                            <ListItemText> Administración </ListItemText>
                                        </ListItemButton>
                                        {openSubmenuAdministracion ? <ExpandLess /> : <ExpandMore />}
                                    </ListItem>
                                    <Collapse in={openSubmenuAdministracion} timeout="auto" unmountOnExit>
                                        <List component="div" disablePadding>
                                           
                                            <ListItem onClick={() => { navigate('/parametros') }} sx={{ marginLeft: 1 }}>
                                                <ListItemIcon>
                                                    <WidgetsIcon />
                                                </ListItemIcon>
                                                <ListItemText secondary="Parametros mensajería" />
                                            </ListItem>
                                            <ListItem onClick={() => { navigate('/usuarios') }} sx={{ marginLeft: 1 }}>
                                                <ListItemIcon>
                                                    <PeopleIcon />
                                                </ListItemIcon>
                                                <ListItemText secondary="Usuarios" />
                                            </ListItem>
                                            <ListItem onClick={() => { navigate('/clientes') }} sx={{ marginLeft: 1 }}>
                                                <ListItemIcon>
                                                    <LocalTaxiIcon />
                                                </ListItemIcon>
                                                <ListItemText secondary="Taxistas" />
                                            </ListItem>
                                            <ListItem onClick={() => { navigate('/enlaces') }} sx={{ marginLeft: 1 }}>
                                                <ListItemIcon>
                                                    <LinkIcon />
                                                </ListItemIcon>
                                                <ListItemText secondary="Enlace de interés" />
                                            </ListItem>
                                        </List>
                                    </Collapse>
                                </List>
                                <List>
                                    <ListItem key='Mensajes' disablePadding onClick={() => { setOpenSubmenuMensajes(!openSubmenuMensajes) }}>
                                        <ListItemButton>
                                            <ListItemIcon>
                                                <RocketLaunchIcon />
                                            </ListItemIcon>
                                            <ListItemText> Mensajes </ListItemText>
                                        </ListItemButton>
                                        {openSubmenuMensajes ? <ExpandLess /> : <ExpandMore />}
                                    </ListItem>
                                    <Collapse in={openSubmenuMensajes} timeout="auto" unmountOnExit>
                                        <List component="div" disablePadding>
                                            <ListItem onClick={() => { navigate('/recursos') }} sx={{ marginLeft: 1 }}>
                                                <ListItemIcon>
                                                    <CloudQueueIcon />
                                                </ListItemIcon>
                                                <ListItemText secondary="Recursos" />
                                            </ListItem>
                                            <ListItem onClick={() => { navigate('/mensajes') }} sx={{ marginLeft: 1 }}>
                                                <ListItemIcon>
                                                    <QuestionAnswerRoundedIcon />
                                                </ListItemIcon>
                                                <ListItemText secondary="Gestión de mensajes" />
                                            </ListItem>
                                        </List>
                                    </Collapse>
                                </List>
                                <Divider />
                                <List>
                                </List>
                            </Box>
                        </Drawer>
                    </Grid>
                    <Grid item xs={12}>
                        <Box component="main" sx={{ flexGrow: 1, p: 5 }} marginTop={5}>
                            {props.children}
                        </Box>
                    </Grid>
                </Grid>


            </Box>
        </div>
    )
}
