import { AppBar, Grid, IconButton, Toolbar, Autocomplete, TextField, Typography} from '@mui/material'
import React, { useContext, useState } from 'react'
import { useMutation, useQuery } from 'react-query'
import { useNavigate } from 'react-router-dom'
import { MenuLateral } from '../../componentes/MenuLateral/MenuLateral'
import { MensajeError } from '../../utilidades/TratamientoErrores'
import { ErrorGeneral } from '../../componentes/ErrorGeneral/ErrorGeneral';
import { LeerClientes, eliminarCliente } from '../../servicios/RQClientes'
import { GeneralCtx } from '../../contextos/GeneralContext'
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';
import { MensajeConfirmacion } from '../../componentes/MensajeConfirmacion/MensajeConfirmacion'
import { MensajeInformativo } from '../../componentes/MensajeInformativo/MensajeInformativo'
import { DataGrid, esES, GridToolbar } from '@mui/x-data-grid';

export const ClientesPagina = (props) => {
    const navigate = useNavigate()
    const { getSession } = useContext(GeneralCtx);
    const [hayError, setHayError] = useState(false);
    const [mensajeError, setMensajeError] = useState('');
    const [hayMensaje, setHayMensaje] = useState(false);
    const [mensaje, setMensaje] = useState('');
    const [hayConfirmacion, setHayConfirmacion] = useState(false);
    const [mensajeConfirmacion, setMensajeConfirmacion] = useState('');
    const [clientes, setClientes] = useState([]);
    const [cliente, setCliente] = useState();
    const [estado, setEstado] = React.useState({  id: 1, text: 'APP DESCARGADA' })

    const estados = [
        {  id: 1, text: 'APP DESCARGADA' },
        {  id: 2, text: 'APP SIN DESCARGAR' },
        {  id: 3, text: 'TODOS' },
      ];
      //const [estado, setEstado] = React.useState(estados.find(option => option.id === 1) || null);


     
    
    const session = getSession()
    const queryUsuarios = useQuery([ 'clientes', estado ], () => { return LeerClientes(estado, session.empresa.empresaId) }, {
        onSuccess: (data) => {
            setClientes(data.data)
        },
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })
    const eliminaCliente = useMutation(({ empresaId, codclien }) => { return eliminarCliente(empresaId, codclien) }, {
        onError: (error) => {
            console.error(error)
            setMensajeError(MensajeError(error))
            setHayError(true)
        }
    })

    const editCliente = (id) => {
        return () => {
            navigate(`/cliente/${id}`)
        }
    }

    const deleteCliente = (row) => {
        return () => {
            setCliente(row)
            setMensajeConfirmacion(`¿Realmente desea eliminar el cliente ${row.nomusu}?`)
            setHayConfirmacion(true)
        }
    }

    const deleteConfirmado = async () => {
        await eliminaCliente.mutateAsync({ empresaId: session.empresa.empresaId, codclien: cliente.codclien })
        queryUsuarios.refetch()
        setHayConfirmacion(false)
        setMensaje(`El cliente ${cliente.nomusu} ha sido eliminado de la base de datos`)
        setHayMensaje(true)
    }

    const columns = [
        { field: 'codclien', headerName: 'ID' },
        { field: 'nomclien', headerName: 'nombre', flex: 1 },
        { field: 'domclien', headerName: 'dirección', flex: 1 },
        { field: 'pobclien', headerName: 'población' },
        { field: 'proclien', headerName: 'provincia' },
        {
            field: 'actions',
            type: 'actions',
            headerName: 'Acciones',
            width: 80,
            getActions: ({row}) => {
                return [<IconButton onClick={deleteCliente(row)}>
                    <DeleteIcon />
                </IconButton>,
                <IconButton onClick={editCliente(row.codclien)}>
                    <EditIcon />
                </IconButton>]
            }
        },
    ]

    return (
        <>
            <MenuLateral>
                <Grid container spacing={2}>
                    <Grid item xs={12}>
                        <AppBar id="imagen" position='static' color='secondary'>
                            <Toolbar>
                                <Typography variant='h6' component='h6'>
                                    Taxistas
                                </Typography>
                            </Toolbar>
                        </AppBar>
                    </Grid>
                    <Grid item xs={11}>
                                        <Autocomplete label="Viajero principal"
                                            id="combo-box-demo"
                                            options={estados}
                                            value={estado}
                                            onChange={(event, newEstado) => {
                                                setEstado(newEstado);
                                              }}
                                            getOptionLabel={(option) => option.text}
                                            isOptionEqualToValue={(option, value) => option.id === value.id} 
                                            style={{ width: 300 }}
                                            renderInput={(params) => <TextField {...params}
                                                label="Opciones de búsqueda"
                                                >
                                            </TextField>}
                                        />
                    </Grid>
                    <Grid item xs={12} style={{ height: '80vh', width: '100%' }}>
                        <DataGrid rows={clientes} columns={columns} getRowId={(row) => row.codclien} components={{Toolbar: GridToolbar}}
                            localeText={esES.components.MuiDataGrid.defaultProps.localeText} />
                    </Grid>
                </Grid>
                <ErrorGeneral hayError={hayError} mensajeError={mensajeError} cerrarError={() => setHayError(false)} />
                <MensajeInformativo hayMensaje={hayMensaje} mensaje={mensaje} cerrarMensaje={() => setHayMensaje(false)} />
                <MensajeConfirmacion hayConfirmacion={hayConfirmacion} mensaje={mensajeConfirmacion} confirmar={deleteConfirmado} cerrarConfirmacion={() => setHayConfirmacion(false)} />
            </MenuLateral>
        </>

    )
}
