import * as yup from 'yup';

export const initialValues = () => {
    return {
        enlaceId: '',
        nombre: '',
        url: ''
    }
}

export const validationSchema = () => {
    return yup.object({
        nombre: yup.string().required('Requerido'),
        url: yup.string().required('Requerido')
    })
}