import * as yup from 'yup';

export const initialValues = () => {
    return {
        administradorId: '',
        empresaId: '',
        nombre: '',
        login: '',
        password: ''
    }
}

export const validationSchema = () => {
    return yup.object({
        nombre: yup.string().required('Requerido'),
        login: yup.string().required('Requerido'),
        password: yup.string().required('Requerido'),
    })
}